const item = $input.first().json || {};
let b = item;
if (b && typeof b === "object" && Object.prototype.hasOwnProperty.call(b, "body")) {
  b = b.body;
}
if (typeof b === "string") {
  try {
    b = JSON.parse(b);
  } catch {
    b = {};
  }
}
if (!b || typeof b !== "object" || Array.isArray(b)) b = {};
const payment = b.payment && typeof b.payment === "object" && !Array.isArray(b.payment) ? b.payment : {};
const customer = b.customer && typeof b.customer === "object" && !Array.isArray(b.customer) ? b.customer : {};

const ALLOWED_EVENT_TYPES = ["payment_failed"];
const ALLOWED_METHODS = ["card", "upi", "netbanking", "wallet", "bank_transfer"];
const errors = [];
function present(v) { return v !== undefined && v !== null && v !== ""; }
function isNum(v) { return v !== null && v !== undefined && v !== "" && !Number.isNaN(Number(v)); }
function num(v) { return isNum(v) ? Number(v) : v; }
function isIso(v) { if (!present(v)) return false; const d = new Date(v); return !Number.isNaN(d.getTime()); }

const paymentId = present(b.payment_id) ? String(b.payment_id) : (present(payment.payment_id) ? String(payment.payment_id) : null);
const topRequired = ["event_id", "event_type", "timestamp", "source", "recovery_attempt_count"];
for (const f of topRequired) { if (!present(b[f]) && b[f] !== 0) errors.push("Missing field: " + f); }
if (!paymentId) errors.push("Missing field: payment_id");
if (!b.payment || typeof b.payment !== "object" || Array.isArray(b.payment)) errors.push("Missing field: payment");
if (!b.customer || typeof b.customer !== "object" || Array.isArray(b.customer)) errors.push("Missing field: customer");

const paymentRequired = ["amount", "currency", "status", "payment_method", "failed_at", "time_since_failure_hours"];
for (const f of paymentRequired) { if (!present(payment[f]) && payment[f] !== 0) errors.push("Missing payment field: " + f); }
const customerRequired = ["customer_id", "notification_count", "customer_age_days", "previous_successful_payments", "previous_failed_payments", "previous_recovery_attempts", "customer_lifetime_value", "average_previous_payment", "recent_payment_frequency"];
for (const f of customerRequired) { if (!present(customer[f]) && customer[f] !== 0) errors.push("Missing customer field: " + f); }

const eventType = typeof b.event_type === "string" ? b.event_type.trim().toLowerCase() : String(b.event_type || "").toLowerCase();
if (present(b.event_type) && !ALLOWED_EVENT_TYPES.includes(eventType)) errors.push("Invalid event_type: " + b.event_type);
const method = typeof payment.payment_method === "string" ? payment.payment_method.trim().toLowerCase() : String(payment.payment_method || "").toLowerCase();
if (present(payment.payment_method) && !ALLOWED_METHODS.includes(method)) errors.push("Invalid payment_method: " + payment.payment_method);
const currency = typeof payment.currency === "string" ? payment.currency.trim().toUpperCase() : String(payment.currency || "").toUpperCase();
if (present(payment.currency) && (currency.length < 1 || currency.length > 3)) errors.push("Invalid currency: " + payment.currency);
if (present(b.timestamp) && !isIso(b.timestamp)) errors.push("Invalid timestamp (not ISO datetime): " + b.timestamp);
if (present(payment.failed_at) && !isIso(payment.failed_at)) errors.push("Invalid payment.failed_at (not ISO datetime): " + payment.failed_at);
if (present(b.recovery_attempt_count) && !isNum(b.recovery_attempt_count)) errors.push("Invalid numeric value: recovery_attempt_count");
for (const f of ["amount", "time_since_failure_hours"]) { if (present(payment[f]) && !isNum(payment[f])) errors.push("Invalid numeric value: payment." + f); }
for (const f of ["notification_count", "customer_age_days", "previous_successful_payments", "previous_failed_payments", "previous_recovery_attempts", "customer_lifetime_value", "average_previous_payment", "recent_payment_frequency"]) { if (present(customer[f]) && !isNum(customer[f])) errors.push("Invalid numeric value: customer." + f); }

const api_payload = {
  event_id: present(b.event_id) ? String(b.event_id) : null,
  event_type: eventType,
  timestamp: b.timestamp,
  source: b.source,
  recovery_attempt_count: num(b.recovery_attempt_count),
  payment_id: paymentId,
  payment: {
    payment_id: paymentId,
    amount: num(payment.amount),
    currency,
    status: payment.status,
    payment_method: method,
    failure_reason: present(payment.failure_reason) ? String(payment.failure_reason) : null,
    failed_at: payment.failed_at,
    time_since_failure_hours: num(payment.time_since_failure_hours)
  },
  customer: {
    customer_id: customer.customer_id,
    notification_count: num(customer.notification_count),
    customer_age_days: num(customer.customer_age_days),
    previous_successful_payments: num(customer.previous_successful_payments),
    previous_failed_payments: num(customer.previous_failed_payments),
    previous_recovery_attempts: num(customer.previous_recovery_attempts),
    customer_lifetime_value: num(customer.customer_lifetime_value),
    average_previous_payment: num(customer.average_previous_payment),
    recent_payment_frequency: num(customer.recent_payment_frequency)
  }
};

return [{
  json: {
    valid: errors.length === 0,
    error_message: errors.length ? errors.join("; ") : null,
    event_id: present(b.event_id) ? String(b.event_id) : null,
    payment_id: paymentId,
    api_payload
  }
}];

const items = $input.all();

function errorOut(message, paymentId, eventId, backendResponse) {
  return [{
    json: {
      ok: false,
      action: "ERROR",
      decision_action: null,
      valid_action: false,
      error_message: message,
      status: "error",
      payment_id: paymentId != null ? paymentId : null,
      event_id: eventId != null ? eventId : null,
      backend_response: backendResponse != null ? backendResponse : null
    }
  }];
}

function unwrap(value) {
  if (value == null) return null;
  if (typeof value === "string") return value;
  if (typeof value !== "object") return null;
  if (Array.isArray(value)) return null;
  if (Object.prototype.hasOwnProperty.call(value, "action") && typeof value.action !== "undefined") return value.action;
  if (Object.prototype.hasOwnProperty.call(value, "body")) return unwrap(value.body);
  if (Object.prototype.hasOwnProperty.call(value, "data")) return unwrap(value.data);
  if (Object.prototype.hasOwnProperty.call(value, "decision")) return unwrap(value.decision);
  if (Object.prototype.hasOwnProperty.call(value, "result")) return unwrap(value.result);
  return null;
}

if (!items.length) {
  return errorOut("Reclaim returned no response.", null, null, null);
}

let data = items[0].json;
if (data && data.error) {
  const err = data.error;
  const httpCode = err.httpCode || (err.context && err.context.httpCode) || null;
  const msg = err.message || err.description || String(err);
  const prefix = String(httpCode) === "422" ? "Reclaim API validation failed: " : "Reclaim API request failed: ";
  return errorOut(prefix + msg, null, null, { error: err });
}
if (typeof data === "string") {
  try { data = JSON.parse(data); } catch (e) {
    return errorOut("Reclaim returned invalid JSON.", null, null, null);
  }
}
if (!data || typeof data !== "object") {
  return errorOut("Reclaim returned an empty response.", null, null, null);
}

const paymentId = data.payment_id != null ? data.payment_id
  : (data.payment && data.payment.payment_id != null ? data.payment.payment_id
  : (data.decision && data.decision.payment_id != null ? data.decision.payment_id : null));
const eventId = data.event_id != null ? data.event_id
  : (data.decision && data.decision.event_id != null ? data.decision.event_id : null);

const allowed = ["RETRY", "PAYMENT_LINK", "REMINDER", "ESCALATE", "STOP"];
let apiAction = unwrap(data);
if (typeof apiAction === "string") apiAction = apiAction.trim().toUpperCase();
if (!apiAction) {
  return errorOut("Recovery action missing from Reclaim response.", paymentId, eventId, data);
}
if (!allowed.includes(apiAction)) {
  return errorOut("Unsupported recovery action: " + apiAction, paymentId, eventId, data);
}

return [{
  json: {
    ok: true,
    action: apiAction,
    decision_action: apiAction,
    valid_action: true,
    status: "success",
    payment_id: paymentId,
    event_id: eventId,
    backend_response: data,
    error_message: null,
    message: "Validated recovery action: " + apiAction + "."
  }
}];
